<script setup lang="ts">
import {useWorkModeText} from '../workMode'
const {w}=useWorkModeText()
import {reviewBoardError} from '../approvalWorkbench'
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePayrollReturn} from '../payrollReturn'
const payrollReturn=usePayrollReturn(),router=useRouter()
import {usePhasePage} from '../phasePage'
import {usePhaseThreeText} from '../phaseThreeText'
import {absenceAllowed,reviewAllowed,reviewEditable,restoreReviewDecisions,reviewText,issueText} from '../attendanceReview'
import {WorkforceApiError} from '../api'
import {hours} from '../time'
import type {ApprovalDetail,ApprovalWrite,ReviewDecision,CalendarPage,CalendarEvent} from '../phaseThreeTypes'
import BreakSummaryTable from '../components/BreakSummaryTable.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
import ReviewExplanationField from '../components/ReviewExplanationField.vue'
import {explanationText,type ReviewExplanation,type ReviewExplanationPage} from '../reviewExplanations'
const props=defineProps<{scheduleId?:string;inline?:boolean}>(),emit=defineEmits<{saved:[]}>()
const id=props.scheduleId||String(useRoute().params.scheduleId),{api,home,current,t,p,base,loading,busy,failure,notice,load,write,format,english}=usePhasePage(),{q,issue}=usePhaseThreeText(),data=ref<ApprovalDetail|null>(null),calendar=ref<CalendarEvent[]>([]),note=ref(''),decisions=ref<ReviewDecision[]>([]),attempt=ref<ApprovalWrite|null>(null)
const explanations=ref<ReviewExplanation[]>([]),explanationFailure=ref(false)
let explanationRevision=0
async function loadExplanations(){if(!home.value?.employeeManage)return;const revision=++explanationRevision;explanationFailure.value=false;try{const page=await api().get<ReviewExplanationPage>('/review-explanations');if(!Array.isArray(page.items))throw new Error('invalid explanation list');if(current()&&revision===explanationRevision)explanations.value=page.items}catch{if(current()&&revision===explanationRevision)explanationFailure.value=true}}
const row=computed(()=>data.value?.row),allowed=computed(()=>data.value?.canReview!==false&&!!row.value&&reviewAllowed(row.value,home.value,decisions.value)),editable=computed(()=>data.value?.canReview!==false&&!!row.value&&reviewEditable(row.value,home.value)),r=(key:Parameters<typeof reviewText>[0])=>reviewText(key,english())
function refresh(){if(attempt.value||busy.value)return;void loadExplanations();data.value=null;calendar.value=[];void load(async()=>{const a=await api().get<ApprovalDetail>('/approvals/'+id),day=a.row.schedule.workDate,c=await api().get<CalendarPage>(`/calendar?from=${day}&to=${day}`);return {a,c}},v=>{data.value=v.a;calendar.value=v.c.items.filter(e=>e.enabled);note.value='';decisions.value=restoreReviewDecisions(v.a.row)})}
function approve(){
 if(busy.value||!row.value)return
 if(!attempt.value){if(!allowed.value||note.value.length>500){failure.value=p('invalid');return}attempt.value={expectedVersion:row.value.approval?.version||0,sourceFingerprint:row.value.sourceFingerprint,note:note.value.trim(),...(row.value.findings?{decisions:decisions.value.map(d=>({...d,note:d.note.trim()}))}:{})}}
 const body=attempt.value
 void write(async()=>{try{await api().put('/approvals/'+id,body);attempt.value=null}catch(e){if(e instanceof WorkforceApiError&&e.status>=400&&e.status<500)attempt.value=null;throw e}},()=>{refreshAfterSave()})
}
function refreshAfterSave(){if(payrollReturn.value&&!props.inline){void router.push(payrollReturn.value);return}data.value=null;void load(()=>api().get<ApprovalDetail>('/approvals/'+id),a=>{data.value=a;decisions.value=restoreReviewDecisions(a.row);note.value='';emit('saved')})}
onMounted(refresh)
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{q('approvalDetail')}}</h2><button :disabled="loading||busy||!!attempt" @click="refresh">{{t('refresh')}}</button></header><RouterLink v-if="payrollReturn&&!inline" :to="payrollReturn">{{english()?'Back to payroll':'返回原工资总表'}}</RouterLink><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><template v-if="row&&data&&!loading"><dl class="wf-details"><dt>{{p('employee')}}</dt><dd>{{row.schedule.employeeName}} · {{row.schedule.employeeNo}}</dd><dt>{{p('workDate')}}</dt><dd>{{row.schedule.workDate}} · {{row.schedule.shift.name}}</dd><dt>{{p('plan')}}</dt><dd>{{format(row.schedule.startAt,row.schedule.timezone)}} – {{format(row.schedule.endAt,row.schedule.timezone)}}</dd><dt>{{q('company')}}</dt><dd>{{home?.companies.find(c=>c.id===row!.schedule.companyId)?.name||row.schedule.companyId}}</dd><dt>{{p('timezone')}}</dt><dd>{{row.schedule.timezone}}</dd><dt>{{english()?'Actual net hours':'实际净工时'}}</dt><dd>{{row.exempt?'—':hours(row.workSeconds)}}</dd><dt>{{english()?'Valid approved hours':'有效核准工时'}}</dt><dd>{{row.exempt?(english()?'Not applicable':'不适用'):row.approval&&!row.requiresReview&&!row.issues.length?hours(row.approval.workSeconds):(english()?'Missing or stale approval':'未核准或已过期')}}</dd><dt>{{q('paidLeave')}}</dt><dd>{{hours(row.paidLeaveSeconds)}}</dd><dt>{{q('unpaidLeave')}}</dt><dd>{{hours(row.unpaidLeaveSeconds)}}</dd><dt>{{p('status')}}</dt><dd><span class="wf-badge" :class="{'wf-badge-warning':row.requiresReview}">{{row.exempt?w('exempt'):q(row.requiresReview?'stale':row.approval?'current':'notApproved')}}</span></dd><dt>{{q('calendar')}}</dt><dd><div v-for="c in calendar" :key="c.id">{{q(c.kind)}} · {{c.name}}</div><span v-if="!calendar.length">—</span></dd><dt>{{p('anomalies')}}</dt><dd><div v-for="code in row.issues" :key="code" class="wf-issue">{{issueText(code,english())!==code?issueText(code,english()):issue(code)}}</div><span v-if="!row.issues.length">{{q('noIssues')}}</span></dd></dl><BreakSummaryTable :summaries="row.breakSummary"/><section v-if="row.findings" class="wf-section"><h3>{{r('review')}}</h3><div v-for="f in row.findings" :key="f.code" class="wf-inline"><strong>{{f.name}}</strong><span>{{hours(f.seconds)}}</span><span>{{f.code==='LEAVE'&&f.status==='confirmed'?r('leaveConfirmed'):r(f.status)}}</span></div><p v-if="row.fullAttendanceStatus">{{r('bonus')}}: <strong>{{r(row.fullAttendanceStatus)}}</strong></p><p class="wf-hint">{{r('bonusHint')}}</p><p v-if="row.findings.some(f=>f.code==='BREAK_MISSING')||row.issues.some(i=>['BREAK_RECORD_MISSING','OPEN_BREAK'].includes(i))" class="wf-hint">{{r('breakMissingHint')}}</p></section><div class="wf-inline"><RouterLink :to="base+'/attendance/'+id">{{q('rawDetails')}}</RouterLink><RouterLink :to="{path:base+'/leaves',query:{from:row.schedule.workDate,to:row.schedule.workDate}}">{{q('leaves')}}</RouterLink></div><p class="wf-hint">{{q('approvalHint')}} {{q('allocationHint')}}</p><details class="wf-source"><summary>{{q('fingerprint')}}</summary><code>{{row.sourceFingerprint}}</code></details><p v-if="data.canReview===false&&data.reviewBlock!=='WORKFORCE_SELF_REVIEW'" class="wf-hint">{{reviewBoardError(data.reviewBlock,english())}}</p><p v-if="home?.myself?.id===row.schedule.employeeId&&home?.employeeManage" class="wf-hint">{{q('reviewSelf')}}</p><p v-else-if="!allowed&&home?.employeeManage&&data.canReview!==false" class="wf-hint">{{q('cannotApprove')}}</p><p v-if="editable&&explanationFailure" class="wf-hint">{{explanationText('unavailable',english())}}</p><form v-if="editable" class="wf-section wf-form-panel" @submit.prevent="approve"><fieldset :disabled="busy||!!attempt"><div v-for="d in decisions" :key="d.code" class="wf-section"><strong>{{row.findings?.find(f=>f.code===d.code)?.name||d.code}}</strong><p v-if="d.code==='MISSING'" class="wf-hint">{{r(absenceAllowed(row)?'absenceHint':'absenceDisabled')}}</p><label>{{r('review')}}<select v-model="d.outcome" required :disabled="d.code==='MISSING'&&!absenceAllowed(row)"><option value="" disabled>{{r('choose')}}</option><option v-if="d.code==='MISSING'&&absenceAllowed(row)" value="absence">{{r('absence')}}</option><template v-else-if="d.code!=='MISSING'"><option value="confirmed">{{r('confirmed')}}</option><option v-if="d.code==='OUTSIDE_SCHEDULE'" value="non_work">{{r('non_work')}}</option><option v-if="!['OUTSIDE_SCHEDULE','DAILY_HOURS_LIMIT','CONTINUOUS_HOURS'].includes(d.code)" value="excused">{{r('excused')}}</option></template></select></label><ReviewExplanationField v-model="d.note" :code="d.code" :items="explanations" :english="english()" :disabled="busy||!!attempt"/></div><label>{{p('note')}} · {{explanationText('optional',english())}}<textarea v-model="note" maxlength="500" rows="3" :disabled="busy"></textarea></label></fieldset><p v-if="decisions.some(d=>d.code==='OUTSIDE_SCHEDULE'&&d.outcome==='non_work')" class="wf-hint">{{english()?'Ask the employee to request a time correction with the actual working times and reason. Independently approve it, then return here. Raw punches remain preserved.':'请员工本人提交补卡，说明实际工作时间及原因；由他人审批后，再返回核工时。原始打卡保留，不直接扣减实际工作。'}} <RouterLink :to="base+'/corrections'">{{english()?'Review corrections':'查看补卡审批'}}</RouterLink></p><p v-if="attempt" role="status" class="wf-hint">{{r('retryHint')}}</p><footer class="wf-form-actions"><button class="primary" :disabled="busy||(!attempt&&!allowed)">{{busy?t('saving'):attempt?r('retry'):q(row.approval?'reconfirm':'confirm')}}</button></footer></form><h2 class="wf-section">{{q('history')}}</h2><article v-for="a in data.history" :key="a.version" class="wf-history"><header class="wf-toolbar"><strong>{{q('version')}} {{a.version}}</strong><span>{{format(a.approvedAt,row.schedule.timezone)}}</span></header><div class="wf-inline"><span>{{q('work')}} {{hours(a.workSeconds)}}</span><span>{{q('paidLeave')}} {{hours(a.paidLeaveSeconds)}}</span><span>{{q('unpaidLeave')}} {{hours(a.unpaidLeaveSeconds)}}</span></div><p>{{p('reviewer')}}: {{a.reviewerId}}</p><p>{{a.note}}</p><div v-for="d in a.decisions||[]" :key="d.code"><strong>{{d.code}} · {{r(d.outcome)}}</strong> · {{d.note}}</div><details class="wf-source"><summary>{{q('source')}}</summary><dl class="wf-details"><dt>{{q('fingerprint')}}</dt><dd><code>{{a.sourceFingerprint}}</code></dd><dt>{{p('employee')}}</dt><dd>{{a.snapshot.schedule.employeeName}} · {{a.snapshot.schedule.employeeNo}}</dd><dt>{{q('company')}}</dt><dd>{{a.snapshot.schedule.companyId}}</dd><dt>{{p('plan')}}</dt><dd>{{format(a.snapshot.schedule.startAt,a.snapshot.schedule.timezone)}} – {{format(a.snapshot.schedule.endAt,a.snapshot.schedule.timezone)}}</dd><dt>{{p('actual')}}</dt><dd>{{format(a.snapshot.session?.inAt,a.snapshot.schedule.timezone)}} – {{format(a.snapshot.session?.outAt,a.snapshot.schedule.timezone)}}</dd><dt>{{q('leaves')}}</dt><dd><div v-for="leave in a.snapshot.leaves" :key="leave.id">{{leave.typeName}} · {{q(leave.status)}} · {{format(leave.startAt,a.snapshot.schedule.timezone)}} – {{format(leave.endAt,a.snapshot.schedule.timezone)}}</div><span v-if="!a.snapshot.leaves.length">—</span></dd><dt>{{q('calendar')}}</dt><dd><div v-for="c in a.snapshot.calendar" :key="c.id">{{q(c.kind)}} · {{c.name}} · {{q(c.enabled?'enabled':'disabled')}}</div><span v-if="!a.snapshot.calendar.length">—</span></dd></dl></details></article><p v-if="!data.history.length" class="wf-empty">{{t('empty')}}</p></template></section></template>

